// ============================================================
// Normalize Existing Feishu Records v1.0
//
// 职责：
// 1. 读取「消费者评价风险处理台_v2」现有业务记录（只读）
// 2. 建立 alert_key -> Feishu record 索引
// 3. 检测重复 alert_key
// 4. 输出规范化后的记录，供 Planner 消费
//
// 本节点不修改飞书。
//
// alert_key = content_key + "::RISK"
//
// 重复 alert_key 处理原则：
// 不自动挑选任何一个。
// 由 Planner 对该 content_key 输出 ERROR_DUPLICATE_ALERT_KEY，
// 并禁止后续写入。
// ============================================================

const response = $input.first().json;

// ------------------------------------------------------------
// 1. 校验飞书读取结果
// ------------------------------------------------------------

if (!response || response.code !== 0) {
  throw new Error(
    `Normalize Existing Feishu Records v1.0: 飞书 v2 读取失败，code=${response?.code}, msg=${response?.msg}`
  );
}

const data = response.data || {};

// 空表时 items 可能为 null
const items = Array.isArray(data.items) ? data.items : [];

// ------------------------------------------------------------
// 2. 安全优先：如果还有下一页，宁可失败也不静默丢数据
// ------------------------------------------------------------

if (data.has_more === true) {
  throw new Error(
    `Normalize Existing Feishu Records v1.0: 飞书 v2 记录数超过单页上限（total=${data.total}），` +
    `请先为工作流增加分页循环，禁止在缺页状态下做同步规划。`
  );
}

// ------------------------------------------------------------
// 3. 字段取值工具
//
// 飞书不同接口版本对单选 / 文本 / 人员 的返回形态不完全一致，
// 这里统一归一化，避免 Planner 里到处判断。
// ------------------------------------------------------------

function one(value) {
  if (value === undefined || value === null) {
    return null;
  }

  if (Array.isArray(value)) {
    return value.length > 0 ? value[0] : null;
  }

  return value;
}

function fsText(value) {
  const v = one(value);
  return v === null ? null : String(v);
}

function fsSelect(value) {
  const v = one(value);
  return v === null ? null : String(v);
}

function fsNumber(value) {
  const v = one(value);

  if (v === null || v === '') {
    return null;
  }

  const n = Number(v);

  return Number.isFinite(n) ? n : null;
}

function fsDateTime(value) {
  const v = one(value);

  if (v === null || v === '') {
    return null;
  }

  const n = Number(v);

  return Number.isFinite(n) ? n : null;
}

function fsUserIds(value) {
  if (!Array.isArray(value)) {
    return null;
  }

  const ids = value
    .map(u => (u && u.id) ? String(u.id) : null)
    .filter(Boolean);

  return ids.length > 0 ? ids : null;
}

// ------------------------------------------------------------
// 4. 规范化每条记录
// ------------------------------------------------------------

const records = items.map(record => {

  const fields = record.fields || {};

  const contentKey = fsText(fields['content_key']);

  return {
    record_id: record.record_id || null,

    alert_key: fsText(fields['alert_key']),

    content_key: contentKey,
    analysis_id: fsNumber(fields['analysis_id']),

    风险等级: fsSelect(fields['风险等级']),
    处理状态: fsSelect(fields['处理状态']),

    风险摘要: fsText(fields['风险摘要']),
    原始评价: fsText(fields['原始评价']),
    风险类别: fsSelect(fields['风险类别']),
    风险子类: fsText(fields['风险子类']),

    商品名称: fsText(fields['商品名称']),
    商品链接: fsText(fields['商品链接']),
    SKU名称: fsText(fields['SKU名称']),
    商品评分: fsNumber(fields['商品评分']),

    平台: fsSelect(fields['平台']),
    店铺: fsSelect(fields['店铺']),

    评价时间: fsDateTime(fields['评价时间']),
    评价ID: fsText(fields['评价ID']),

    商品ID: fsText(fields['商品ID']),
    SKU_ID: fsText(fields['SKU_ID']),

    负责人: fsUserIds(fields['负责人']),
    处理备注: fsText(fields['处理备注']),

    首次同步时间: fsDateTime(fields['首次同步时间']),
    最近同步时间: fsDateTime(fields['最近同步时间'])
  };
});

// ------------------------------------------------------------
// 5. 重复 alert_key 检测
//
// 同一个 alert_key 对应多条飞书记录时：
// 不做任何自动取舍。
// ------------------------------------------------------------

const alertKeyCount = {};

for (const record of records) {
  const key = record.alert_key;

  if (!key) {
    continue;
  }

  alertKeyCount[key] = (alertKeyCount[key] || 0) + 1;
}

const duplicateAlertKeys =
  Object.keys(alertKeyCount)
    .filter(key => alertKeyCount[key] > 1);

// ------------------------------------------------------------
// 6. 输出
//
// 输出 1 个 item，包含：
// - feishu_total
// - duplicate_alert_keys
// - records[]
// ============================================================

return [
  {
    json: {
      feishu_table: '消费者评价风险处理台_v2',
      feishu_total: records.length,
      duplicate_alert_keys: duplicateAlertKeys,
      records: records
    }
  }
];

// ============================================================
// Plan Feishu Risk Sync v1.0
//
// 职责：
// PostgreSQL current analysis snapshot
//   -> 与飞书 v2 现有工单对比
//   -> 输出 sync_action
//
// sync_action 取值：
// CREATE     飞书无对应 alert_key，且 PG 当前为 P0/P1 有效风险
// UPDATE     飞书已有 alert_key，需要刷新系统字段 / 状态迁移
// INVALIDATE PG 当前不再是有效风险（OUT_OF_SCOPE 或 P2/P3/NONE），飞书置「已失效」
// NOOP       无需任何变更；不刷新「最近同步时间」
// ERROR      数据或状态无法安全解释，禁止写入
//
// 本节点只生成计划。
// 绝不调用任何飞书写接口。
// ============================================================


// ============================================================
// 0. 输入
// ============================================================

const snapshotRows =
  $('Read Current Analysis Snapshot - PostgreSQL')
    .all()
    .map(item => item.json);

const feishuState =
  $('Normalize Existing Feishu Records v1.0')
    .first().json;

const feishuRecords =
  Array.isArray(feishuState.records) ? feishuState.records : [];

const duplicateAlertKeys =
  new Set(
    Array.isArray(feishuState.duplicate_alert_keys)
      ? feishuState.duplicate_alert_keys
      : []
  );


// ============================================================
// 1. 常量与白名单
// ============================================================

const VALID_RISK_LEVELS = ['P0', 'P1'];

const STATUS_PENDING = '待处理';
const STATUS_INVALID = '已失效';

const KNOWN_ANALYSIS_SCOPES = ['IN_SCOPE', 'OUT_OF_SCOPE'];

// 首次创建时允许写入的系统 + 状态字段
const CREATE_FIELDS = [
  '风险等级', '处理状态', '负责人', '处理备注',
  '风险摘要', '原始评价', '风险类别', '风险子类',
  '商品名称', '商品链接', 'SKU名称', '商品评分',
  '平台', '店铺', '评价时间', '评价ID',
  'alert_key', 'content_key', 'analysis_id', '商品ID', 'SKU_ID',
  '首次同步时间', '最近同步时间'
];

// 普通 UPDATE 允许写入 —— 明确不含：
// 负责人 / 处理备注（人工字段，无条件保护）
// 首次同步时间（CREATE only）
const UPDATE_SYSTEM_FIELDS = [
  '风险等级',
  '风险摘要', '原始评价', '风险类别', '风险子类',
  '商品名称', '商品链接', 'SKU名称', '商品评分',
  '平台', '店铺', '评价时间', '评价ID',
  'alert_key', 'content_key', 'analysis_id', '商品ID', 'SKU_ID',
  '最近同步时间'
];

// INVALIDATE 只允许写这 3 个字段
const INVALIDATE_FIELDS = [
  '处理状态', 'analysis_id', '最近同步时间'
];

const syncTimestampMs = Date.now();


// ============================================================
// 2. 工具函数
// ============================================================

function normalizeNullable(value) {

  if (value === undefined || value === null || value === '') {
    return null;
  }

  return String(value);
}

function alertKeyOf(contentKey) {
  return String(contentKey) + '::RISK';
}

// ------------------------------------------------------------
// 时区规则（关键）
//
// raw_reviews.content_time 是 timestamp WITHOUT time zone。
// 业务语义固定为 Asia/Shanghai。
//
// 因此：
// 不带时区信息的字符串 -> 显式补 +08:00 再解析
// 已带 Z / +08:00      -> 直接解析
//
// 绝不允许依赖运行环境时区产生 ±8 小时漂移。
// ------------------------------------------------------------
function toShanghaiTimestamp(value) {

  if (value === null || value === undefined || value === '') {
    return null;
  }

  if (typeof value === 'number' && Number.isFinite(value)) {
    return value;
  }

  const text = String(value).trim();

  const hasExplicitZone =
    /Z$/i.test(text) || /[+-]\d{2}:?\d{2}$/.test(text);

  if (hasExplicitZone) {

    const ts = Date.parse(text);

    if (Number.isNaN(ts)) {
      throw new Error(`无法解析日期时间：${value}`);
    }

    return ts;
  }

  const normalized =
    text.indexOf('T') >= 0 ? text : text.replace(' ', 'T');

  const ts = Date.parse(`${normalized}+08:00`);

  if (Number.isNaN(ts)) {
    throw new Error(`无法解析日期时间：${value}`);
  }

  return ts;
}

// ------------------------------------------------------------
// 系统字段 signature
//
// 用于判断「飞书当前系统字段是否已经过期」。
// 不含 analysis_id（单独判断）
// 不含 负责人 / 处理备注 / 处理状态（人工字段）
// 不含 首次同步时间 / 最近同步时间（同步运维字段）
// ------------------------------------------------------------
function buildSystemSignature(source) {

  return JSON.stringify({
    风险等级: normalizeNullable(source['风险等级']),
    风险摘要: normalizeNullable(source['风险摘要']),
    原始评价: normalizeNullable(source['原始评价']),
    风险类别: normalizeNullable(source['风险类别']),
    风险子类: normalizeNullable(source['风险子类']),
    商品名称: normalizeNullable(source['商品名称']),
    商品链接: normalizeNullable(source['商品链接']),
    SKU名称: normalizeNullable(source['SKU名称']),
    商品评分: source['商品评分'] === null || source['商品评分'] === undefined
      ? null
      : String(source['商品评分']),
    平台: normalizeNullable(source['平台']),
    店铺: normalizeNullable(source['店铺']),
    评价时间: source['评价时间_feishu'] === null || source['评价时间_feishu'] === undefined
      ? null
      : String(source['评价时间_feishu']),
    评价ID: normalizeNullable(source['评价ID']),
    商品ID: normalizeNullable(source['商品ID']),
    SKU_ID: normalizeNullable(source['SKU_ID'])
  });
}


// ============================================================
// 3. 建立 alert_key -> Feishu record 索引
// ============================================================

const recordIndexByAlertKey = {};

for (const record of feishuRecords) {

  const key = record.alert_key;

  if (!key) {
    continue;
  }

  if (!recordIndexByAlertKey[key]) {
    recordIndexByAlertKey[key] = [];
  }

  recordIndexByAlertKey[key].push(record);
}

const consumedRecordIds = new Set();


// ============================================================
// 4. 逐条规划
// ============================================================

const plans = [];

for (const row of snapshotRows) {

  const contentKey = normalizeNullable(row.content_key);
  const alertKey = contentKey ? alertKeyOf(contentKey) : null;

  const analysisId = row.analysis_id === null || row.analysis_id === undefined
    ? null
    : Number(row.analysis_id);

  const analysisScope = normalizeNullable(row.analysis_scope);
  const analysisStatus = normalizeNullable(row.analysis_status);
  const newRiskLevel = normalizeNullable(row.final_risk_level);

  const feishuMatched = alertKey ? (recordIndexByAlertKey[alertKey] || []) : [];

  for (const r of feishuMatched) {
    if (r.record_id) {
      consumedRecordIds.add(r.record_id);
    }
  }

  let contentTimeOriginal = null;
  let contentTimeFeishu = null;

  if (row.content_time !== null && row.content_time !== undefined) {
    contentTimeOriginal = String(row.content_time);
    contentTimeFeishu = toShanghaiTimestamp(row.content_time);
  }

  // ----------------------------------------------------------
  // 基础行
  // ----------------------------------------------------------
  const base = {
  content_key: contentKey,
  alert_key: alertKey,
  analysis_id: analysisId,
  feishu_record_id: feishuMatched.length === 1
    ? feishuMatched[0].record_id
    : null,

  new_risk_level: newRiskLevel,
  analysis_scope: analysisScope,
  analysis_status: analysisStatus,

  content_time_original: contentTimeOriginal,
  content_time_feishu: contentTimeFeishu,

  platform: normalizeNullable(row.platform),
  shop_name: normalizeNullable(row.shop_name),

  // 商品 / 评价业务字段
  content_text: normalizeNullable(row.content_text),
  product_id: normalizeNullable(row.product_id),
  product_name: normalizeNullable(row.product_name),
  sku_id: normalizeNullable(row.sku_id),
  sku_name: normalizeNullable(row.sku_name),
  product_rating:
    row.product_rating === null || row.product_rating === undefined
      ? null
      : Number(row.product_rating),

  source_review_id: normalizeNullable(row.source_review_id),

  // 风险分析结果
  risk_summary: normalizeNullable(row.final_summary),
  risk_category: normalizeNullable(row.final_category),
  risk_subcategory: normalizeNullable(row.final_subcategory),

  sync_planned_at: new Date(syncTimestampMs).toISOString()
};

  // ----------------------------------------------------------
  // 异常保护 1：重复 alert_key
  // 禁止自动挑选，禁止该 content_key 后续写入
  // ----------------------------------------------------------
  if (alertKey && duplicateAlertKeys.has(alertKey)) {

    plans.push({
      ...base,
      sync_action: 'ERROR',
      sync_reason: 'ERROR_DUPLICATE_ALERT_KEY: 同一 alert_key 在飞书 v2 中存在多条记录，禁止自动选取，禁止本次继续执行写入。',
      error_code: 'ERROR_DUPLICATE_ALERT_KEY',
      duplicate_record_count: feishuMatched.length,
      duplicate_record_ids: feishuMatched.map(r => r.record_id),
      old_risk_level: null,
      old_processing_status: null,
      target_processing_status: null,
      system_fields_to_write: []
    });

    continue;
  }

  // ----------------------------------------------------------
  // 异常保护 2：关联的 raw_reviews 缺失
  // ----------------------------------------------------------
  if (!row.source_review_id && !row.content_text) {

    plans.push({
      ...base,
      sync_action: 'ERROR',
      sync_reason: 'ERROR_RAW_REVIEW_MISSING: analysis_results 存在 current 分析，但 raw_reviews 未关联到对应 content_key，数据关联异常。',
      error_code: 'ERROR_RAW_REVIEW_MISSING',
      old_risk_level: null,
      old_processing_status: null,
      target_processing_status: null,
      system_fields_to_write: []
    });

    continue;
  }

  // ----------------------------------------------------------
  // 异常保护 3：analysis_scope / analysis_status 无法解释
  // ----------------------------------------------------------
  if (!analysisScope || KNOWN_ANALYSIS_SCOPES.indexOf(analysisScope) < 0) {

    plans.push({
      ...base,
      sync_action: 'ERROR',
      sync_reason: `ERROR_UNEXPLAINABLE_SCOPE: analysis_scope=${analysisScope} 无法解释，禁止自动变更飞书工单。`,
      error_code: 'ERROR_UNEXPLAINABLE_SCOPE',
      old_risk_level: null,
      old_processing_status: null,
      target_processing_status: null,
      system_fields_to_write: []
    });

    continue;
  }

  if (analysisStatus !== 'SUCCESS') {

    plans.push({
      ...base,
      sync_action: 'ERROR',
      sync_reason: `ERROR_ANALYSIS_NOT_SUCCESS: analysis_status=${analysisStatus}，禁止自动失效或写入。`,
      error_code: 'ERROR_ANALYSIS_NOT_SUCCESS',
      old_risk_level: null,
      old_processing_status: null,
      target_processing_status: null,
      system_fields_to_write: []
    });

    continue;
  }

  // ----------------------------------------------------------
  // 业务判定准备
  // ----------------------------------------------------------
  const isInScope = analysisScope === 'IN_SCOPE';
  const isActiveRisk = VALID_RISK_LEVELS.indexOf(newRiskLevel) >= 0;
  const isSyncCandidate = isInScope && isActiveRisk;

  const existing = feishuMatched.length === 1 ? feishuMatched[0] : null;
  const oldRiskLevel = existing ? existing['风险等级'] : null;
  const oldStatus = existing ? existing['处理状态'] : null;

  // PG 侧应有的系统字段值
  const pgSystemView = {
    风险等级: isSyncCandidate ? newRiskLevel : (existing ? existing['风险等级'] : null),
    风险摘要: normalizeNullable(row.final_summary),
    原始评价: normalizeNullable(row.content_text),
    风险类别: normalizeNullable(row.final_category),
    风险子类: normalizeNullable(row.final_subcategory),
    商品名称: normalizeNullable(row.product_name),
    商品链接: null,
    SKU名称: normalizeNullable(row.sku_name),
    商品评分: row.product_rating === null || row.product_rating === undefined
      ? null
      : Number(row.product_rating),
    平台: normalizeNullable(row.platform),
    店铺: normalizeNullable(row.shop_name),
    评价时间_feishu: contentTimeFeishu,
    评价ID: normalizeNullable(row.source_review_id),
    商品ID: normalizeNullable(row.product_id),
    SKU_ID: normalizeNullable(row.sku_id)
  };

  const feishuSystemView = existing
    ? {
        风险等级: existing['风险等级'],
        风险摘要: existing['风险摘要'],
        原始评价: existing['原始评价'],
        风险类别: existing['风险类别'],
        风险子类: existing['风险子类'],
        商品名称: existing['商品名称'],
        商品链接: existing['商品链接'],
        SKU名称: existing['SKU名称'],
        商品评分: existing['商品评分'],
        平台: existing['平台'],
        店铺: existing['店铺'],
        评价时间_feishu: existing['评价时间'],
        评价ID: existing['评价ID'],
        商品ID: existing['商品ID'],
        SKU_ID: existing['SKU_ID']
      }
    : null;

  const analysisIdChanged = existing
    ? (existing['analysis_id'] !== analysisId)
    : true;

  const systemFieldsStale = existing
    ? (buildSystemSignature(pgSystemView) !== buildSystemSignature(feishuSystemView))
    : true;

  // ==========================================================
  // 分支 A：飞书不存在该 alert_key
  // ==========================================================
  if (!existing) {

    if (isSyncCandidate) {

      plans.push({
        ...base,
        sync_action: 'CREATE',
        sync_reason: 'CREATE_NEW_RISK_TICKET: PG 当前为 IN_SCOPE / SUCCESS / P0|P1，飞书无对应 alert_key，创建客服工单。',
        error_code: null,
        old_risk_level: null,
        old_processing_status: null,
        target_processing_status: STATUS_PENDING,
        system_fields_to_write: CREATE_FIELDS,
        preserve_human_fields: false
      });

    } else {

      plans.push({
        ...base,
        sync_action: 'NOOP',
        sync_reason: `NOOP_NOT_RISK_AND_NO_TICKET: analysis_scope=${analysisScope}, final_risk_level=${newRiskLevel}，本就不需要飞书工单。`,
        error_code: null,
        old_risk_level: null,
        old_processing_status: null,
        target_processing_status: null,
        system_fields_to_write: []
      });

    }

    continue;
  }

  // ==========================================================
  // 分支 B：飞书已存在该 alert_key，但 PG 当前不再是有效风险
  // -> INVALIDATE（禁止删除，禁止写 P2/P3/NONE 到风险等级）
  // ==========================================================
  if (!isSyncCandidate) {

    const alreadyInvalid = oldStatus === STATUS_INVALID;

    if (alreadyInvalid && !analysisIdChanged) {

      plans.push({
        ...base,
        sync_action: 'NOOP',
        sync_reason: `NOOP_ALREADY_INVALID: 飞书已为「已失效」且 analysis_id 未变化（${analysisId}），不重复刷新最近同步时间。`,
        error_code: null,
        old_risk_level: oldRiskLevel,
        old_processing_status: oldStatus,
        target_processing_status: STATUS_INVALID,
        system_fields_to_write: []
      });

    } else {

      plans.push({
        ...base,
        sync_action: 'INVALIDATE',
        sync_reason: `INVALIDATE_RISK_GONE: analysis_scope=${analysisScope}, final_risk_level=${newRiskLevel}，工单置「已失效」，保留负责人 / 处理备注 / 首次同步时间；风险等级不改写为 P2/P3/NONE。`,
        error_code: null,
        old_risk_level: oldRiskLevel,
        old_processing_status: oldStatus,
        target_processing_status: STATUS_INVALID,
        system_fields_to_write: INVALIDATE_FIELDS
      });

    }

    continue;
  }

  // ==========================================================
  // 分支 C：飞书已存在，PG 当前仍是 P0/P1 有效风险
  // ==========================================================

  let targetStatus = oldStatus;
  let statusReason = null;

  // C-1 风险升级：P1 -> P0，强制回到「待处理」
  if (oldRiskLevel === 'P1' && newRiskLevel === 'P0') {

    targetStatus = STATUS_PENDING;
    statusReason = 'RISK_UPGRADED_P1_TO_P0';

  }
  // C-2 重新激活：已失效的工单重新成为有效风险
  else if (oldStatus === STATUS_INVALID) {

    targetStatus = STATUS_PENDING;
    statusReason = 'REACTIVATED_FROM_INVALID';

  }
  // C-3 风险降级 P0 -> P1：状态保持原样
  else if (oldRiskLevel === 'P0' && newRiskLevel === 'P1') {

    targetStatus = oldStatus;
    statusReason = 'RISK_DOWNGRADED_P0_TO_P1_KEEP_STATUS';

  }
  // C-4 人工状态保护：其余情况不覆盖人工状态
  else {

    targetStatus = oldStatus;
    statusReason = 'KEEP_HUMAN_STATUS';

  }

  const statusChanged = targetStatus !== oldStatus;

  const needsUpdate =
    analysisIdChanged ||
    systemFieldsStale ||
    statusChanged;

  if (!needsUpdate) {

    plans.push({
      ...base,
      sync_action: 'NOOP',
      sync_reason: `NOOP_EVERYTHING_CURRENT: analysis_id=${analysisId} 未变化，系统字段一致，无需状态修正。NOOP 不刷新最近同步时间。`,
      error_code: null,
      old_risk_level: oldRiskLevel,
      old_processing_status: oldStatus,
      target_processing_status: oldStatus,
      system_fields_to_write: []
    });

    continue;
  }

  const fields = UPDATE_SYSTEM_FIELDS.slice();

  if (statusChanged) {
    fields.push('处理状态');
  }

  plans.push({
    ...base,
    sync_action: 'UPDATE',
    sync_reason: `UPDATE_SYSTEM_FIELDS: analysis_id_changed=${analysisIdChanged}, system_fields_stale=${systemFieldsStale}, status_rule=${statusReason}。保留负责人 / 处理备注 / 首次同步时间。`,
    error_code: null,
    old_risk_level: oldRiskLevel,
    old_processing_status: oldStatus,
    target_processing_status: targetStatus,
    system_fields_to_write: fields,
    status_rule: statusReason
  });
}


// ============================================================
// 5. 孤儿飞书工单检测
//
// 飞书有记录，但 PG 当前找不到对应的 SUCCESS current analysis。
// 可能是：
// - content_key 根本没有 current analysis
// - 当前 analysis_status = ERROR
// - 数据关联异常
//
// 按异常保护规则 13：
// 绝对不能因为查不到结果就把工单自动设为已失效。
// ============================================================

for (const record of feishuRecords) {

  if (record.record_id && consumedRecordIds.has(record.record_id)) {
    continue;
  }

  const key = record.alert_key;

  if (!key) {

    plans.push({
      content_key: record.content_key,
      alert_key: null,
      analysis_id: record.analysis_id,
      feishu_record_id: record.record_id,
      sync_action: 'ERROR',
      sync_reason: 'ERROR_FEISHU_RECORD_WITHOUT_ALERT_KEY: 飞书工单缺少 alert_key，无法参与幂等匹配，禁止自动处理。',
      error_code: 'ERROR_FEISHU_RECORD_WITHOUT_ALERT_KEY',
      old_risk_level: record['风险等级'],
      old_processing_status: record['处理状态'],
      target_processing_status: null,
      system_fields_to_write: []
    });

    continue;
  }

  if (duplicateAlertKeys.has(key)) {
    continue;
  }

  plans.push({
    content_key: record.content_key,
    alert_key: key,
    analysis_id: record.analysis_id,
    feishu_record_id: record.record_id,
    sync_action: 'ERROR',
    sync_reason: 'ERROR_ORPHAN_FEISHU_RECORD: 飞书存在工单，但 PG 当前没有对应的 SUCCESS current analysis（可能为 ERROR 状态 / 无 current 记录 / 关联异常）。按异常保护规则，禁止自动置为已失效。',
    error_code: 'ERROR_ORPHAN_FEISHU_RECORD',
    old_risk_level: record['风险等级'],
    old_processing_status: record['处理状态'],
    target_processing_status: null,
    system_fields_to_write: []
  });
}


// ============================================================
// 6. 输出
// ============================================================

return plans.map(plan => ({ json: plan }));

